// Only the Latin variable-weight faces used by the UI; served from our own origin.
export default async function vendorFonts({ packageVersion, readText, copy, writeText }) {
  const faces = [
    ["@fontsource-variable/inter", "inter"],
    ["@fontsource-variable/jetbrains-mono", "jetbrains-mono"],
  ];
  const rules = [];
  for (const [pkg, family] of faces) {
    const version = await packageVersion(pkg);
    if (version !== "5.3.0") throw new Error(`Review font vendoring before upgrading ${pkg}@${version}`);
    for (const style of ["normal", "italic"]) {
      const css = await readText(pkg, style === "normal" ? "wght.css" : "wght-italic.css");
      const name = `${family}-latin-wght-${style}.woff2`;
      const block = [...css.matchAll(/\/\*[^*]+\*\/\s*@font-face\s*\{[^}]+\}/g)].find((match) => match[0].includes(`./files/${name}`))?.[0];
      if (!block) throw new Error(`Latin font-face missing for ${name}`);
      rules.push(block.replaceAll("./files/", "./"));
      await copy(pkg, `files/${name}`, `fonts/${name}`);
    }
    await copy(pkg, "LICENSE", `fonts/LICENSE-${family}.txt`);
  }
  await writeText("fonts/fonts.css", `/* Latin variable fonts from @fontsource-variable/inter@5.3.0 and @fontsource-variable/jetbrains-mono@5.3.0. SIL OFL 1.1; see LICENSE-*.txt. Generated by npm run vendor. */\n${rules.join("\n\n")}\n`);
  await writeText("fonts/README.md", `# Local UI fonts\n\nInter Variable and JetBrains Mono Variable, each from the pinned Fontsource package version 5.3.0 (SIL Open Font License 1.1).\n\nOnly Latin variable-weight WOFF2 normal and italic faces are copied from each package's files/ directory. fonts.css extracts the matching @font-face blocks from wght.css and wght-italic.css, rewriting their URLs to this folder. The two LICENSE-*.txt files are copied verbatim from the packages.\n\nRegenerate with npm ci and npm run vendor (scripts/vendor/fonts.mjs). tokens.css imports fonts.css; no CDN, remote font URL or runtime provider call is needed.\n`);
}
